      for (char c : word.toCharArray()) {
        p = p.child[index(c)];
        p.pass--;
      }
      p.end--;
      return true;
    }
  }

  public static String solve(String[] words) {
    Trie t = new Trie();
    for (String w : words) t.insert(w);
    String best = "";
    for (String w : words) {
      Node p = t.root;
      boolean valid = true;
      for (char c : w.toCharArray()) {
        p = p.child[c - 'a'];
        if (p.end == 0) {
          valid = false;
          break;
        }
      }
      if (valid
          && (w.length() > best.length() || w.length() == best.length() && w.compareTo(best) < 0))
        best = w;
    }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve(new String[] {"n", "ni", "nin", "ninj", "ninja", "ninga"}));
  }
}

Number of distinct substrings in a strin.source:
import java.util.*;

public class Solution {
  static class Node {
    Node[] child = new Node[26];
  }

  public static long solve(String s) {
    for (char c : s.toCharArray()) if (c < 'a' || c > 'z') throw new IllegalArgumentException();
    Node root = new Node();
    long count = 1;
    for (int start = 0; start < s.length(); start++) {
      Node p = root;
      for (int end = start; end < s.length(); end++) {
        int x = s.charAt(end) - 'a';
        if (p.child[x] == null) {
          p.child[x] = new Node();
          count++;
        }
        p = p.child[x];
      }
    }
    return count;
  }

  public static void main(String[] args) {
    System.out.println(solve("ababa"));
  }
}

Maximum XOR of two numbers in an array.source:
import java.util.*;

public class Solution {
  static class BitNode {
    BitNode[] child = new BitNode[2];
  }

  static void insert(BitNode root, int x) {
    if (x < 0) throw new IllegalArgumentException();
    BitNode p = root;
    for (int bit = 30; bit >= 0; bit--) {
      int b = (x >>> bit) & 1;
      if (p.child[b] == null) p.child[b] = new BitNode();
      p = p.child[b];
    }
  }

  static int query(BitNode root, int x) {
    if (x < 0) throw new IllegalArgumentException();
    int ans = 0;
    BitNode p = root;
    for (int bit = 30; bit >= 0; bit--) {
      int b = (x >>> bit) & 1;
      if (p.child[1 - b] != null) {
        ans |= 1 << bit;
        p = p.child[1 - b];
      } else p = p.child[b];
    }
    return ans;
  }

  public static int solve(int[] a) {
    if (a.length < 2) return 0;
    BitNode root = new BitNode();
    insert(root, a[0]);
    int best = 0;
    for (int i = 1; i < a.length; i++) {
      best = Math.max(best, query(root, a[i]));
      insert(root, a[i]);
    }
    return best;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {3, 10, 5, 25, 2, 8}));
  }
}

